-- PEAK Scientific (new brand): Genius XE, Precision Series (hydrogen, hydrogen trace, nitrogen, nitrogen trace, zero air, air compressor, Hydrogen SL),
-- Solaris 1010A and Intura (H2, N2, ZA, N2|ZA) gas generators. From the PEAK Scientific datasheets and brochures.
-- Photos: public/products/peak-scientific/, logo: public/brands/peak-scientific.png.
-- Run in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again: products are updated by SKU.
alter table products add column if not exists features jsonb not null default '[]'::jsonb;
insert into brands (name, slug, website_url) values ('PEAK Scientific', 'peak-scientific', 'https://www.peakscientific.com/')
on conflict (slug) do update set name = excluded.name, website_url = coalesce(brands.website_url, excluded.website_url);
insert into categories (name, slug, sort_order) values ('Equipment', 'equipment', 5) on conflict (slug) do nothing;

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('PEAK-GENIUS-XE-35', 'PEAK Scientific Genius XE 35 Nitrogen Generator for LC-MS (35 L/min)', 'peak-scientific-genius-xe-35-nitrogen-generator-for-lc-ms-35-l-min-peak-genius-xe-35', 'Genius XE 35 is a premium standalone nitrogen generator for high-performance LC-MS, delivering up to 35 L/min of nitrogen at up to 99.5 % purity on demand, 24/7, with a fixed annual service interval. Applications: LC-MS (including high-sensitivity instruments), ELSD, small sample evaporators and other lab nitrogen uses.', '[["Model", "Genius XE 35"], ["Part number", "3300252 (230 VAC) / 3300807 (120 VAC)"], ["Max flow", "Up to 35 L/min"], ["Max pressure", "116 psi (8 bar)"], ["Gas outlet", "1 × ¼\" BSPP"], ["Purity", "95 to 99.5 % (factory certified, O2 basis; min. 95 % at max flow)"], ["Particles", "< 0.01 µm"], ["Phthalates", "Phthalate and BHT free"], ["Suspended liquids", "None"], ["NMHC", "< 1 ppm"], ["Operating conditions", "5 to 35 °C; max 80 % RH at 31 °C; up to 3000 m"], ["Electrical", "120 VAC 60 Hz 12 A or 230 VAC 50/60 Hz 8 A"], ["Power consumption", "960 VA (120 V) / 1265 VA (230 V)"], ["Heat output", "4118 BTU"], ["Noise", "56 dB"], ["Dimensions (H × W × D)", "650 × 570 × 710 mm"], ["Weight", "92 kg"]]', '["Multi-Stage Purification™: analytical-grade nitrogen up to 99.5 %", "ECO (Electronic Compressor Optimisation™) for low energy use and compressor durability", "Variable flow and pressure up to 116 psi (8 bar)", "Full-colour touch-screen; on-board service scheduling and diagnostics", "Smaller and quieter than the previous Genius generation", "2-year comprehensive warranty (year 2 with annual service)"]', 'equipment', '/products/peak-scientific/genius-xe.jpg'),
  ('PEAK-GENIUS-XE-70', 'PEAK Scientific Genius XE 70 Nitrogen Generator for LC-MS (70 L/min)', 'peak-scientific-genius-xe-70-nitrogen-generator-for-lc-ms-70-l-min-peak-genius-xe-70', 'Genius XE 70 is a premium standalone nitrogen generator for high-performance LC-MS, delivering up to 70 L/min of nitrogen at up to 99.5 % purity on demand, 24/7, with extra compressor capacity for lower-flow applications. Applications: LC-MS (including high-sensitivity instruments), ELSD, small sample evaporators and other lab nitrogen uses.', '[["Model", "Genius XE 70"], ["Part number", "3300253 (230 VAC)"], ["Max flow", "Up to 70 L/min"], ["Max pressure", "116 psi (8 bar)"], ["Gas outlet", "1 × ¼\" BSPP"], ["Purity", "95 to 99.5 % (factory certified, O2 basis; min. 95 % at max flow)"], ["Particles", "< 0.01 µm"], ["Phthalates", "Phthalate and BHT free"], ["Suspended liquids", "None"], ["NMHC", "< 1 ppm"], ["Operating conditions", "5 to 35 °C; max 80 % RH at 31 °C; up to 3000 m"], ["Electrical", "230 VAC 50/60 Hz 12 A"], ["Power consumption", "2530 VA"], ["Heat output", "8785 BTU"], ["Noise", "59 dB"], ["Dimensions (H × W × D)", "1000 × 570 × 710 mm"], ["Weight", "147 kg"]]', '["Multi-Stage Purification™: analytical-grade nitrogen up to 99.5 %", "ECO (Electronic Compressor Optimisation™) for low energy use and compressor durability", "Variable flow and pressure up to 116 psi (8 bar)", "Full-colour touch-screen; on-board service scheduling and diagnostics", "Smaller and quieter than the previous Genius generation", "2-year comprehensive warranty (year 2 with annual service)", "Additional compressor capacity for lower-flow applications"]', 'equipment', '/products/peak-scientific/genius-xe.jpg'),
  ('PEAK-PRECISION-H2-SL-100', 'PEAK Scientific Precision Hydrogen SL 100cc Generator for GC-FID', 'peak-scientific-precision-hydrogen-sl-100cc-generator-for-gc-fid-peak-precision-h2-sl-100', 'Precision Hydrogen SL 100cc is PEAK''s smallest hydrogen generator for GC flame detectors, producing 100 cc/min of 99.9995 % hydrogen safely and simply, with far less stored gas than a cylinder.', '[["Model", "Precision Hydrogen SL 100cc"], ["Part numbers", "Manual fill 3302946 (black) / 3302943 (white); auto water fill 3302947 / 3302944; pressurised fill 3302948 / 3302945"], ["Max flow", "100 cc/min"], ["Water consumption", "Up to 0.12 L/day"], ["Max pressure", "100 psi / 6.9 bar"], ["Purity", "99.9995 %"], ["Gas outlet", "1 × 1/8\" Swagelok compression fitting"], ["Water purity", "ASTM Type II (< 1 µS/cm)"], ["Dew point", "-60 °C"], ["Operating temperature", "10 to 35 °C"], ["Electrical", "100 to 240 V ±10 %, 50/60 Hz, 6 A max"], ["Power consumption", "83.8 to 102 VA"], ["Heat output", "983 BTU/hr"], ["Dimensions (H × W × D)", "250 × 160 × 355 mm"], ["Weight", "8 kg"], ["Consumables", "Desiccant capsule 3302581; de-ioniser cartridge 3302583"]]', '["Smallest hydrogen generator for GC-FID, minimal bench space", "99.9995 % purity at 100 psi", "One-button start-up and shutdown", "Easy end-user servicing", "Optional auto water fill or pressurised water fill", "Auto-shutdown fail-safe; stores minimal hydrogen", "Black or white; 2-year warranty"]', 'equipment', '/products/peak-scientific/precision-hydrogen-sl.jpg'),
  ('PEAK-PRECISION-H2-SL-200', 'PEAK Scientific Precision Hydrogen SL 200cc Generator for GC-FID', 'peak-scientific-precision-hydrogen-sl-200cc-generator-for-gc-fid-peak-precision-h2-sl-200', 'Precision Hydrogen SL 200cc is PEAK''s smallest hydrogen generator for GC flame detectors, producing 200 cc/min of 99.9995 % hydrogen safely and simply, with far less stored gas than a cylinder.', '[["Model", "Precision Hydrogen SL 200cc"], ["Part numbers", "Manual fill 3302952 (black) / 3302949 (white); auto water fill 3302953 / 3302950; pressurised fill 3302954 / 3302951"], ["Max flow", "200 cc/min"], ["Water consumption", "Up to 0.24 L/day"], ["Max pressure", "100 psi / 6.9 bar"], ["Purity", "99.9995 %"], ["Gas outlet", "1 × 1/8\" Swagelok compression fitting"], ["Water purity", "ASTM Type II (< 1 µS/cm)"], ["Dew point", "-60 °C"], ["Operating temperature", "10 to 35 °C"], ["Electrical", "100 to 240 V ±10 %, 50/60 Hz, 6 A max"], ["Power consumption", "83.8 to 102 VA"], ["Heat output", "983 BTU/hr"], ["Dimensions (H × W × D)", "250 × 160 × 355 mm"], ["Weight", "8 kg"], ["Consumables", "Desiccant capsule 3302581; de-ioniser cartridge 3302583"]]', '["Smallest hydrogen generator for GC-FID, minimal bench space", "99.9995 % purity at 100 psi", "One-button start-up and shutdown", "Easy end-user servicing", "Optional auto water fill or pressurised water fill", "Auto-shutdown fail-safe; stores minimal hydrogen", "Black or white; 2-year warranty"]', 'equipment', '/products/peak-scientific/precision-hydrogen-sl.jpg'),
  ('PEAK-PRECISION-AIR-COMPRESSOR', 'PEAK Scientific Precision Air Compressor Module', 'peak-scientific-precision-air-compressor-module-peak-precision-air-compressor', 'The Precision Air Compressor is a dedicated, stackable compressed-air module for Precision Nitrogen and Precision Zero Air generators, giving a complete self-contained GC gas solution where no house air supply is available. A duplex mounting system keeps noise and vibration low.', '[["Part number", "65-0555 (230 V) / 65-1555 (110 V)"], ["Max pressure", "120 psi / 8.27 bar"], ["Gas outlet", "1 × ¼\" BSPP"], ["Operating temperature", "5 to 35 °C"], ["Electrical", "110-115 V 50/60 Hz 5.2 A or 208-230 V 50/60 Hz 2.45 A"], ["Power consumption", "510 W (110 V) / < 600 W (230 V)"], ["Heat output", "1740 to 3922 BTU/hr"], ["Dimensions (W × D × H)", "380 × 540 × 406 mm"], ["Weight", "42 kg"], ["Annual service kit", "08-8372"], ["Maintenance plans", "Standard 09-3110; Complete 09-3010"]]', '["One unit can supply both Precision Nitrogen and Zero Air in a stack", "Same compact, stackable form factor as Precision generators", "Duplex compressor mounting dampens noise and vibration", "Service and repair status indicators", "12-month comprehensive on-site warranty"]', 'equipment', '/products/peak-scientific/precision-air-compressor.jpg'),
  ('PEAK-61-0250', 'PEAK Scientific Precision Nitrogen 250cc Generator for GC', 'peak-scientific-precision-nitrogen-250cc-generator-for-gc-peak-61-0250', 'Precision Nitrogen 250cc supplies a constant, consistent source of > 99.9995 % nitrogen at up to 250 cc/min for GC detector make-up gas and sample preparation, in a compact stackable module.', '[["Part number", "61-0250"], ["Max flow", "250 cc/min"], ["Weight", "21 kg"], ["Max pressure", "80 psi / 5.5 bar"], ["Purity", "> 99.9995 %"], ["Gas outlet", "1 × ¼\" BSPP"], ["Air inlet", "6.9 to 8.3 bar (100 to 120 psi), min. 35 L/min, ISO 8573-1:2010 Class 1.4.1"], ["Start-up time to purity", "1.5 hours"], ["Operating temperature", "5 to 35 °C"], ["Electrical", "110 VAC 60 Hz 0.37 A / 230 VAC 50 Hz 0.17 A"], ["Power consumption", "39.1 to 40.7 W"], ["Dimensions (W × D × H)", "380 × 540 × 256 mm"], ["Service kit", "08-3612"], ["Air compressor option", "Precision Air Compressor 65-0555 (230 V) / 65-1555 (110 V)"]]', '["Make-up gas at standard detection limits; headspace, purge & trap, tube conditioning, sample blow-down", "PSA with carbon molecular sieve removes oxygen and moisture", "Nitrogen on demand: never run out mid-analysis", "Compact, modular and stackable with other Precision units", "Minimum maintenance: annual filter change"]', 'equipment', '/products/peak-scientific/precision-nitrogen.jpg'),
  ('PEAK-61-0600', 'PEAK Scientific Precision Nitrogen 600cc Generator for GC', 'peak-scientific-precision-nitrogen-600cc-generator-for-gc-peak-61-0600', 'Precision Nitrogen 600cc supplies a constant, consistent source of > 99.9995 % nitrogen at up to 600 cc/min for GC detector make-up gas and sample preparation, in a compact stackable module.', '[["Part number", "61-0600"], ["Max flow", "600 cc/min"], ["Weight", "21 kg"], ["Max pressure", "80 psi / 5.5 bar"], ["Purity", "> 99.9995 %"], ["Gas outlet", "1 × ¼\" BSPP"], ["Air inlet", "6.9 to 8.3 bar (100 to 120 psi), min. 35 L/min, ISO 8573-1:2010 Class 1.4.1"], ["Start-up time to purity", "1.5 hours"], ["Operating temperature", "5 to 35 °C"], ["Electrical", "110 VAC 60 Hz 0.37 A / 230 VAC 50 Hz 0.17 A"], ["Power consumption", "39.1 to 40.7 W"], ["Dimensions (W × D × H)", "380 × 540 × 256 mm"], ["Service kit", "08-3612"], ["Air compressor option", "Precision Air Compressor 65-0555 (230 V) / 65-1555 (110 V)"]]', '["Make-up gas at standard detection limits; headspace, purge & trap, tube conditioning, sample blow-down", "PSA with carbon molecular sieve removes oxygen and moisture", "Nitrogen on demand: never run out mid-analysis", "Compact, modular and stackable with other Precision units", "Minimum maintenance: annual filter change"]', 'equipment', '/products/peak-scientific/precision-nitrogen.jpg'),
  ('PEAK-61-1000', 'PEAK Scientific Precision Nitrogen 1L Generator for GC', 'peak-scientific-precision-nitrogen-1l-generator-for-gc-peak-61-1000', 'Precision Nitrogen 1L supplies a constant, consistent source of > 99.9995 % nitrogen at up to 1000 cc/min for GC detector make-up gas and sample preparation, in a compact stackable module.', '[["Part number", "61-1000"], ["Max flow", "1000 cc/min"], ["Weight", "26 kg"], ["Max pressure", "80 psi / 5.5 bar"], ["Purity", "> 99.9995 %"], ["Gas outlet", "1 × ¼\" BSPP"], ["Air inlet", "6.9 to 8.3 bar (100 to 120 psi), min. 35 L/min, ISO 8573-1:2010 Class 1.4.1"], ["Start-up time to purity", "1.5 hours"], ["Operating temperature", "5 to 35 °C"], ["Electrical", "110 VAC 60 Hz 0.37 A / 230 VAC 50 Hz 0.17 A"], ["Power consumption", "39.1 to 40.7 W"], ["Dimensions (W × D × H)", "380 × 540 × 256 mm"], ["Service kit", "08-3612"], ["Air compressor option", "Precision Air Compressor 65-0555 (230 V) / 65-1555 (110 V)"]]', '["Make-up gas at standard detection limits; headspace, purge & trap, tube conditioning, sample blow-down", "PSA with carbon molecular sieve removes oxygen and moisture", "Nitrogen on demand: never run out mid-analysis", "Compact, modular and stackable with other Precision units", "Minimum maintenance: annual filter change"]', 'equipment', '/products/peak-scientific/precision-nitrogen.jpg'),
  ('PEAK-60-1500', 'PEAK Scientific Precision Zero Air 1.5L Generator for GC', 'peak-scientific-precision-zero-air-1-5l-generator-for-gc-peak-60-1500', 'Precision Zero Air 1.5L supplies clean, dry, hydrocarbon-free air (< 0.05 ppm) at up to 1.5 L/min as GC detector gas, in a compact stackable Precision module.', '[["Part number", "60-1500 (230 V) / 60-1501 (110 V)"], ["Max flow", "1.5 L/min"], ["Max pressure", "80 psi / 5.5 bar"], ["Air inlet", "90 to 145 psi (6.2 to 10 bar), min. 1.5 L/min"], ["Electrical", "230 VAC 2 A / 110 VAC 1 A"], ["Power consumption", "230 W @ 230 V / 220 W @ 110 V"], ["Dimensions (W × D × H)", "380 × 540 × 156 mm"], ["Weight", "16 kg"], ["Hydrocarbons", "< 0.05 ppm (as methane)"], ["Gas outlet", "1 × 1/8\" BSPP"], ["Dew point", "-30 °C"], ["Start-up time", "60 minutes"], ["Min inlet air quality", "ISO 8573-1:2010 Class 1.4.1"], ["Operating temperature", "5 to 35 °C"], ["Service kit", "08-3611"]]', '["Clean, dry, hydrocarbon-free air for GC flame detectors", "Hydrocarbons < 0.05 ppm (as methane)", "No expensive catalyst chamber replacements", "Integrates with other Precision units; compatible with Precision Air Compressor", "Status lighting: amber warm-up, green ready", "12-month on-site warranty"]', 'equipment', '/products/peak-scientific/precision-zero-air.jpg'),
  ('PEAK-60-3500', 'PEAK Scientific Precision Zero Air 3.5L Generator for GC', 'peak-scientific-precision-zero-air-3-5l-generator-for-gc-peak-60-3500', 'Precision Zero Air 3.5L supplies clean, dry, hydrocarbon-free air (< 0.05 ppm) at up to 3.5 L/min as GC detector gas, in a compact stackable Precision module.', '[["Part number", "60-3500 (230 V) / 60-3501 (110 V)"], ["Max flow", "3.5 L/min"], ["Max pressure", "80 psi / 5.5 bar"], ["Air inlet", "90 to 145 psi (6.2 to 10 bar), min. 3.5 L/min"], ["Electrical", "230 VAC 2 A / 110 VAC 1 A"], ["Power consumption", "230 W @ 230 V / 220 W @ 110 V"], ["Dimensions (W × D × H)", "380 × 540 × 156 mm"], ["Weight", "16 kg"], ["Hydrocarbons", "< 0.05 ppm (as methane)"], ["Gas outlet", "1 × 1/8\" BSPP"], ["Dew point", "-30 °C"], ["Start-up time", "60 minutes"], ["Min inlet air quality", "ISO 8573-1:2010 Class 1.4.1"], ["Operating temperature", "5 to 35 °C"], ["Service kit", "08-3611"]]', '["Clean, dry, hydrocarbon-free air for GC flame detectors", "Hydrocarbons < 0.05 ppm (as methane)", "No expensive catalyst chamber replacements", "Integrates with other Precision units; compatible with Precision Air Compressor", "Status lighting: amber warm-up, green ready", "12-month on-site warranty"]', 'equipment', '/products/peak-scientific/precision-zero-air.jpg'),
  ('PEAK-60-0007', 'PEAK Scientific Precision Zero Air 7L Generator for GC', 'peak-scientific-precision-zero-air-7l-generator-for-gc-peak-60-0007', 'Precision Zero Air 7L supplies clean, dry, hydrocarbon-free air (< 0.05 ppm) at up to 7 L/min as GC detector gas, in a compact stackable Precision module.', '[["Part number", "60-0007 (230 V) / 60-0008 (110 V)"], ["Max flow", "7 L/min"], ["Max pressure", "80 psi / 5.5 bar"], ["Air inlet", "110 to 125 psi (7.5 to 8.6 bar), min. 7 L/min"], ["Electrical", "230 VAC 5.4 A / 110 VAC 3.3 A"], ["Power consumption", "759 W @ 230 V / 594 W @ 110 V"], ["Dimensions (W × D × H)", "380 × 540 × 256 mm"], ["Weight", "25 kg"], ["Hydrocarbons", "< 0.05 ppm (as methane)"], ["Gas outlet", "1 × 1/8\" BSPP"], ["Dew point", "-30 °C"], ["Start-up time", "60 minutes"], ["Min inlet air quality", "ISO 8573-1:2010 Class 1.4.1"], ["Operating temperature", "5 to 35 °C"], ["Service kit", "08-3611"]]', '["Clean, dry, hydrocarbon-free air for GC flame detectors", "Hydrocarbons < 0.05 ppm (as methane)", "No expensive catalyst chamber replacements", "Integrates with other Precision units; compatible with Precision Air Compressor", "Status lighting: amber warm-up, green ready", "12-month on-site warranty"]', 'equipment', '/products/peak-scientific/precision-zero-air.jpg'),
  ('PEAK-60-0018', 'PEAK Scientific Precision Zero Air 18L Generator for GC', 'peak-scientific-precision-zero-air-18l-generator-for-gc-peak-60-0018', 'Precision Zero Air 18L supplies clean, dry, hydrocarbon-free air (< 0.05 ppm) at up to 18 L/min as GC detector gas, in a compact stackable Precision module.', '[["Part number", "60-0018 (230 V) / 60-0019 (110 V)"], ["Max flow", "18 L/min"], ["Max pressure", "80 psi / 5.5 bar"], ["Air inlet", "110 to 125 psi (7.5 to 8.6 bar), min. 18 L/min"], ["Electrical", "230 VAC 5.4 A / 110 VAC 3.3 A"], ["Power consumption", "759 W @ 230 V / 594 W @ 110 V"], ["Dimensions (W × D × H)", "380 × 540 × 256 mm"], ["Weight", "25 kg"], ["Hydrocarbons", "< 0.05 ppm (as methane)"], ["Gas outlet", "1 × 1/8\" BSPP"], ["Dew point", "-30 °C"], ["Start-up time", "60 minutes"], ["Min inlet air quality", "ISO 8573-1:2010 Class 1.4.1"], ["Operating temperature", "5 to 35 °C"], ["Service kit", "08-3611"]]', '["Clean, dry, hydrocarbon-free air for GC flame detectors", "Hydrocarbons < 0.05 ppm (as methane)", "No expensive catalyst chamber replacements", "Integrates with other Precision units; compatible with Precision Air Compressor", "Status lighting: amber warm-up, green ready", "12-month on-site warranty"]', 'equipment', '/products/peak-scientific/precision-zero-air.jpg'),
  ('PEAK-60-0030', 'PEAK Scientific Precision Zero Air 30L Generator for GC', 'peak-scientific-precision-zero-air-30l-generator-for-gc-peak-60-0030', 'Precision Zero Air 30L supplies clean, dry, hydrocarbon-free air (< 0.05 ppm) at up to 30 L/min as GC detector gas, in a compact stackable Precision module.', '[["Part number", "60-0030 (230 V) / 60-0031 (110 V)"], ["Max flow", "30 L/min"], ["Max pressure", "100 psi / 6.9 bar"], ["Air inlet", "110 to 145 psi (7.6 to 10 bar), min. 30 L/min"], ["Electrical", "230 VAC 11 A / 110 VAC 6.7 A"], ["Power consumption", "1541 W @ 230 V / 1210 W @ 110 V"], ["Dimensions (W × D × H)", "380 × 540 × 405 mm"], ["Weight", "41 kg"], ["Hydrocarbons", "< 0.05 ppm (as methane)"], ["Gas outlet", "1 × 1/8\" BSPP"], ["Dew point", "-30 °C"], ["Start-up time", "60 minutes"], ["Min inlet air quality", "ISO 8573-1:2010 Class 1.4.1"], ["Operating temperature", "5 to 35 °C"], ["Service kit", "08-3611"]]', '["Clean, dry, hydrocarbon-free air for GC flame detectors", "Hydrocarbons < 0.05 ppm (as methane)", "No expensive catalyst chamber replacements", "Integrates with other Precision units; compatible with Precision Air Compressor", "Status lighting: amber warm-up, green ready", "12-month on-site warranty"]', 'equipment', '/products/peak-scientific/precision-zero-air.jpg'),
  ('PEAK-PRECISION-H2-100', 'PEAK Scientific Precision Hydrogen 100cc Generator for GC', 'peak-scientific-precision-hydrogen-100cc-generator-for-gc-peak-precision-h2-100', 'Precision Hydrogen 100cc generates 99.9995 % hydrogen on demand at up to 100 cc/min for GC flame detector fuel gas, a safer alternative to hydrogen cylinders. From the Precision Series range for GC and GC-MS: modular, stackable generators with internal leak detection and auto-shutdown on hydrogen models, 12-month warranty and 3-year PEM cell warranty on hydrogen models.', '[["Model", "Precision Hydrogen 100cc"], ["Gas", "Hydrogen"], ["Max flow", "100 cc/min"], ["Purity", "99.9995 %"], ["Max pressure", "100 psi"], ["Accessories", "4 L or 8 L water bottle; GC in-oven hydrogen leak detector"]]', '["Hydrogen on demand for GC flame detectors", "Internal leak detection, auto-shutdown and low stored volume", "Stacks with Precision Nitrogen and Zero Air", "3-year PEM cell warranty"]', 'equipment', '/products/peak-scientific/precision-stack.jpg'),
  ('PEAK-PRECISION-H2-200', 'PEAK Scientific Precision Hydrogen 200cc Generator for GC', 'peak-scientific-precision-hydrogen-200cc-generator-for-gc-peak-precision-h2-200', 'Precision Hydrogen 200cc generates 99.9995 % hydrogen on demand at up to 200 cc/min for GC flame detector fuel gas, a safer alternative to hydrogen cylinders. From the Precision Series range for GC and GC-MS: modular, stackable generators with internal leak detection and auto-shutdown on hydrogen models, 12-month warranty and 3-year PEM cell warranty on hydrogen models.', '[["Model", "Precision Hydrogen 200cc"], ["Gas", "Hydrogen"], ["Max flow", "200 cc/min"], ["Purity", "99.9995 %"], ["Max pressure", "100 psi"], ["Accessories", "4 L or 8 L water bottle; GC in-oven hydrogen leak detector"]]', '["Hydrogen on demand for GC flame detectors", "Internal leak detection, auto-shutdown and low stored volume", "Stacks with Precision Nitrogen and Zero Air", "3-year PEM cell warranty"]', 'equipment', '/products/peak-scientific/precision-stack.jpg'),
  ('PEAK-PRECISION-H2-300', 'PEAK Scientific Precision Hydrogen 300cc Generator for GC', 'peak-scientific-precision-hydrogen-300cc-generator-for-gc-peak-precision-h2-300', 'Precision Hydrogen 300cc generates 99.9995 % hydrogen on demand at up to 300 cc/min for GC flame detector fuel gas, a safer alternative to hydrogen cylinders. From the Precision Series range for GC and GC-MS: modular, stackable generators with internal leak detection and auto-shutdown on hydrogen models, 12-month warranty and 3-year PEM cell warranty on hydrogen models.', '[["Model", "Precision Hydrogen 300cc"], ["Gas", "Hydrogen"], ["Max flow", "300 cc/min"], ["Purity", "99.9995 %"], ["Max pressure", "100 psi"], ["Accessories", "4 L or 8 L water bottle; GC in-oven hydrogen leak detector"]]', '["Hydrogen on demand for GC flame detectors", "Internal leak detection, auto-shutdown and low stored volume", "Stacks with Precision Nitrogen and Zero Air", "3-year PEM cell warranty"]', 'equipment', '/products/peak-scientific/precision-stack.jpg'),
  ('PEAK-PRECISION-H2-450', 'PEAK Scientific Precision Hydrogen 450cc Generator for GC', 'peak-scientific-precision-hydrogen-450cc-generator-for-gc-peak-precision-h2-450', 'Precision Hydrogen 450cc generates 99.9995 % hydrogen on demand at up to 450 cc/min for GC flame detector fuel gas, a safer alternative to hydrogen cylinders. From the Precision Series range for GC and GC-MS: modular, stackable generators with internal leak detection and auto-shutdown on hydrogen models, 12-month warranty and 3-year PEM cell warranty on hydrogen models.', '[["Model", "Precision Hydrogen 450cc"], ["Gas", "Hydrogen"], ["Max flow", "450 cc/min"], ["Purity", "99.9995 %"], ["Max pressure", "100 psi"], ["Accessories", "4 L or 8 L water bottle; GC in-oven hydrogen leak detector"]]', '["Hydrogen on demand for GC flame detectors", "Internal leak detection, auto-shutdown and low stored volume", "Stacks with Precision Nitrogen and Zero Air", "3-year PEM cell warranty"]', 'equipment', '/products/peak-scientific/precision-stack.jpg'),
  ('PEAK-PRECISION-H2-1200', 'PEAK Scientific Precision Hydrogen 1.2L Generator for GC', 'peak-scientific-precision-hydrogen-1-2l-generator-for-gc-peak-precision-h2-1200', 'Precision Hydrogen 1.2L generates 99.9995 % hydrogen on demand at up to 1.2 L/min for GC flame detector fuel gas, a safer alternative to hydrogen cylinders. From the Precision Series range for GC and GC-MS: modular, stackable generators with internal leak detection and auto-shutdown on hydrogen models, 12-month warranty and 3-year PEM cell warranty on hydrogen models.', '[["Model", "Precision Hydrogen 1.2L"], ["Gas", "Hydrogen"], ["Max flow", "1.2 L/min"], ["Purity", "99.9995 %"], ["Max pressure", "100 psi"], ["Accessories", "4 L or 8 L water bottle; GC in-oven hydrogen leak detector"]]', '["Hydrogen on demand for GC flame detectors", "Internal leak detection, auto-shutdown and low stored volume", "Stacks with Precision Nitrogen and Zero Air", "3-year PEM cell warranty"]', 'equipment', '/products/peak-scientific/precision-stack.jpg'),
  ('PEAK-PRECISION-H2-TRACE-250', 'PEAK Scientific Precision Hydrogen Trace 250cc Generator for GC-MS Carrier Gas', 'peak-scientific-precision-hydrogen-trace-250cc-generator-for-gc-ms-carrier-gas-peak-precision-h2-trace-250', 'Precision Hydrogen Trace 250cc produces 99.99999 % hydrogen (O2 basis, verified by the UK National Physical Laboratory) as GC and GC-MS carrier gas: a cost-effective alternative to helium with up to 40 % faster run times. From the Precision Series range for GC and GC-MS: modular, stackable generators with internal leak detection and auto-shutdown on hydrogen models, 12-month warranty and 3-year PEM cell warranty on hydrogen models.', '[["Model", "Precision Hydrogen Trace 250cc"], ["Gas", "Hydrogen (carrier grade)"], ["Max flow", "250 cc/min"], ["Purity", "99.99999 % (O2 content, NPL verified)"], ["Max pressure", "100 psi"], ["Accessories", "4 L or 8 L water bottle; GC in-oven hydrogen leak detector"]]', '["Helium alternative for GC and GC-MS carrier gas", "Run times up to 40 % faster than helium", "Internal leak detection, auto-shutdown and low stored volume", "3-year PEM cell warranty"]', 'equipment', '/products/peak-scientific/precision-stack.jpg'),
