  ('PEAK-PRECISION-H2-TRACE-1200', 'PEAK Scientific Precision Hydrogen Trace 1.2L Generator for GC-MS Carrier Gas', 'peak-scientific-precision-hydrogen-trace-1-2l-generator-for-gc-ms-carrier-gas-peak-precision-h2-trace-1200', 'Precision Hydrogen Trace 1.2L produces 99.99999 % hydrogen (O2 basis, verified by the UK National Physical Laboratory) as GC and GC-MS carrier gas: a cost-effective alternative to helium with up to 40 % faster run times. From the Precision Series range for GC and GC-MS: modular, stackable generators with internal leak detection and auto-shutdown on hydrogen models, 12-month warranty and 3-year PEM cell warranty on hydrogen models.', '[["Model", "Precision Hydrogen Trace 1.2L"], ["Gas", "Hydrogen (carrier grade)"], ["Max flow", "1.2 L/min"], ["Purity", "99.99999 % (O2 content, NPL verified)"], ["Max pressure", "100 psi"], ["Accessories", "4 L or 8 L water bottle; GC in-oven hydrogen leak detector"]]', '["Helium alternative for GC and GC-MS carrier gas", "Run times up to 40 % faster than helium", "Internal leak detection, auto-shutdown and low stored volume", "3-year PEM cell warranty"]', 'equipment', '/products/peak-scientific/precision-stack.jpg'),
  ('PEAK-PRECISION-N2-TRACE-250', 'PEAK Scientific Precision Nitrogen Trace 250cc Generator (Zero Nitrogen)', 'peak-scientific-precision-nitrogen-trace-250cc-generator-zero-nitrogen-peak-precision-n2-trace-250', 'Precision Nitrogen Trace 250cc supplies zero-grade nitrogen (99.9995 %, < 0.05 ppm NMHC) at up to 250 cc/min for GC carrier gas with FID, ECD or TCD and detector make-up gas. From the Precision Series range for GC and GC-MS: modular, stackable generators with internal leak detection and auto-shutdown on hydrogen models, 12-month warranty and 3-year PEM cell warranty on hydrogen models.', '[["Model", "Precision Nitrogen Trace 250cc"], ["Gas", "Zero nitrogen"], ["Max flow", "250 cc/min"], ["Purity", "99.9995 % / < 0.05 ppm NMHC"], ["Max pressure", "80 psi"]]', '["Zero nitrogen for GC carrier and detector gas", "Helium alternative for GC-ECD and GC-TCD", "Stacks with other Precision modules; optional Precision Air Compressor"]', 'equipment', '/products/peak-scientific/precision-nitrogen.jpg'),
  ('PEAK-PRECISION-N2-TRACE-600', 'PEAK Scientific Precision Nitrogen Trace 600cc Generator (Zero Nitrogen)', 'peak-scientific-precision-nitrogen-trace-600cc-generator-zero-nitrogen-peak-precision-n2-trace-600', 'Precision Nitrogen Trace 600cc supplies zero-grade nitrogen (99.9995 %, < 0.05 ppm NMHC) at up to 600 cc/min for GC carrier gas with FID, ECD or TCD and detector make-up gas. From the Precision Series range for GC and GC-MS: modular, stackable generators with internal leak detection and auto-shutdown on hydrogen models, 12-month warranty and 3-year PEM cell warranty on hydrogen models.', '[["Model", "Precision Nitrogen Trace 600cc"], ["Gas", "Zero nitrogen"], ["Max flow", "600 cc/min"], ["Purity", "99.9995 % / < 0.05 ppm NMHC"], ["Max pressure", "80 psi"]]', '["Zero nitrogen for GC carrier and detector gas", "Helium alternative for GC-ECD and GC-TCD", "Stacks with other Precision modules; optional Precision Air Compressor"]', 'equipment', '/products/peak-scientific/precision-nitrogen.jpg'),
  ('PEAK-PRECISION-N2-TRACE-1000', 'PEAK Scientific Precision Nitrogen Trace 1L Generator (Zero Nitrogen)', 'peak-scientific-precision-nitrogen-trace-1l-generator-zero-nitrogen-peak-precision-n2-trace-1000', 'Precision Nitrogen Trace 1L supplies zero-grade nitrogen (99.9995 %, < 0.05 ppm NMHC) at up to 1 L/min for GC carrier gas with FID, ECD or TCD and detector make-up gas. From the Precision Series range for GC and GC-MS: modular, stackable generators with internal leak detection and auto-shutdown on hydrogen models, 12-month warranty and 3-year PEM cell warranty on hydrogen models.', '[["Model", "Precision Nitrogen Trace 1L"], ["Gas", "Zero nitrogen"], ["Max flow", "1 L/min"], ["Purity", "99.9995 % / < 0.05 ppm NMHC"], ["Max pressure", "80 psi"]]', '["Zero nitrogen for GC carrier and detector gas", "Helium alternative for GC-ECD and GC-TCD", "Stacks with other Precision modules; optional Precision Air Compressor"]', 'equipment', '/products/peak-scientific/precision-nitrogen.jpg'),
  ('PEAK-PRECISION-N2-HEADSPACE-250', 'PEAK Scientific Precision Nitrogen Headspace 250cc Generator', 'peak-scientific-precision-nitrogen-headspace-250cc-generator-peak-precision-n2-headspace-250', 'Precision Nitrogen Headspace 250cc supplies 99.9995 % nitrogen at up to 250 cc/min and a higher 100 psi output for headspace vial pressurisation. From the Precision Series range for GC and GC-MS: modular, stackable generators with internal leak detection and auto-shutdown on hydrogen models, 12-month warranty and 3-year PEM cell warranty on hydrogen models.', '[["Model", "Precision Nitrogen Headspace 250cc"], ["Gas", "Nitrogen"], ["Max flow", "250 cc/min"], ["Purity", "99.9995 %"], ["Max pressure", "100 psi"]]', '["Higher 100 psi output for headspace", "Nitrogen on demand; never run out mid-analysis", "Stacks with other Precision modules"]', 'equipment', '/products/peak-scientific/precision-nitrogen.jpg'),
  ('PEAK-SOLARIS-1010A', 'PEAK Scientific Solaris 1010A Nitrogen Generator for ELSD and Compact MS', 'peak-scientific-solaris-1010a-nitrogen-generator-for-elsd-and-compact-ms-peak-solaris-1010a', 'Solaris 1010A uses membrane technology and a built-in air compressor to supply up to 10 L/min of nitrogen (up to 99.5 %) for ELSD with HPLC, compact mass spectrometers and TLD readers, with outlet pressure adjustable to 100 psi.', '[["Part number", "3305373 (220-240 V) / 3305374 (120 V)"], ["Max flow", "10 L/min"], ["Max pressure", "100 psi / 6.89 bar"], ["Purity", "Up to 99.5 % at 4 L/min (97.5 % at 10 L/min)"], ["Gas outlets", "1 × ¼\" BSPP and 1 × 6 mm push-fit"], ["Power consumption", "680 W"], ["Electrical", "120 V ±5 % 60 Hz / 220-240 V ±10 % 50/60 Hz"], ["Noise", "< 58 dB(A) at 1 m"], ["Operating conditions", "5 to 35 °C; max 80 % RH; up to 2000 m"], ["Dimensions (H × W × D)", "453 × 417 × 540 mm"], ["Weight", "31.5 kg"], ["Service kits", "Annual 3305027; 4-year 3305028 (230 V) / 3305029 (120 V)"]]', '["Supports up to 2 ELSDs, 1 compact MS or TLD readers", "Built-in air compressor saves lab space", "Full-colour touch-screen", "Proven membrane technology", "12-month on-site warranty"]', 'equipment', '/products/peak-scientific/solaris-1010a.jpg'),
