  ('PEAK-INTURA-N2-250', 'PEAK Scientific Intura N2 250 Nitrogen Generator for GC', 'peak-scientific-intura-n2-250-nitrogen-generator-for-gc-peak-intura-n2-250', 'Intura N2 250 supplies ultra-high-purity nitrogen (99.9995 %, < 10 ppm CO2) at up to 250 cc/min and 100 psi for GC detector make-up gas and sample preparation. Its high-efficiency PSA purifier needs less compressed air, lowering power use and heat output.', '[["Part number", "3305330-0-01"], ["Max flow", "250 cc/min"], ["Output pressure", "100 psi / 6.9 bar"], ["Purity", "99.9995 %; CO / NOx / SOx / phthalate free"], ["CO2", "< 10 ppm"], ["CH4", "< 0.05 ppm when supplied by Intura ZA"], ["Dew point", "-65 °C"], ["Power consumption", "40 W"], ["Electrical", "Universal 100-240 V 50/60 Hz"], ["Dimensions (H × W × D)", "220 × 330 × 520 mm"], ["Weight", "20 kg"], ["Noise", "< 35 dB(A)"], ["Max altitude", "3000 m"], ["Warranty", "12 months (extendable to 5 years)"]]', '["Up to 1 L/min UHP nitrogen at 100 psi", "Purity safeguard ensures only UHP gas reaches the GC", "High-efficiency PSA purifier, ultra-low power", "For headspace, purge & trap, tube conditioning and make-up gas", "Compact design", "12-month comprehensive warranty, extendable up to 5 years (select regions)"]', 'equipment', '/products/peak-scientific/intura-nitrogen.jpg'),
